:root {
  --cream: #f5ecd7;
  --rust: #b94a2c;
  --forest: #3a5e3f;
  --tan: #d9c8a8;
  --ink: #2b1f14;
  --muted: #7a6a55;
}

.seed-packet {
  width: 280px;
  background-color: var(--cream);
  border: 3px solid var(--rust);
  border-radius: 6px;
  overflow: hidden;
  margin: 40px auto;
}

.packet-header {
  background-color: var(--rust);
  padding: 12px 16px 10px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
}

.packet-year {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 3px;
  color: var(--tan);
  text-transform: uppercase;
}

.packet-name {
  font-size: 20px;
  font-weight: 800;
  color: var(--cream);
  margin: 0;
  text-align: center;
  line-height: 1.2;
}

.packet-latin {
  font-size: 11px;
  font-style: italic;
  color: var(--tan);
}

.packet-body {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 14px 18px;
}

.seed-icon {
  margin: 0;
  font-size: 44px;
  line-height: 1;
}

.grow-info {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1;
}

.grow-info li {
  display: flex;
  justify-content: space-between;
  align-items: center;
  border-bottom: 1px dashed var(--tan);
  padding-bottom: 4px;
}

.label {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--muted);
}

.value {
  font-size: 13px;
  font-weight: 700;
  color: var(--forest);
}
